const nextCallWork = `-- name: NextCallWork :one
SELECT coalesce(min(next_attempt_at) FILTER (WHERE lease_until IS NULL OR lease_until <= $1::timestamptz),
                '0001-01-01 00:00:00+00')::timestamptz AS free_at,
       coalesce(min(lease_until) FILTER (WHERE lease_until > $1::timestamptz),
                '0001-01-01 00:00:00+00')::timestamptz AS lease_end
FROM gateway_calls
WHERE org_id = $2 AND state IN ('waiting', 'sending') AND next_attempt_at IS NOT NULL
`

type NextCallWorkParams struct {
	Now   time.Time
	OrgID int64
}

type NextCallWorkRow struct {
	FreeAt   time.Time
	LeaseEnd time.Time
}

// NextCallWork is when the next call can be claimed: the earliest due time of a call without a live lease (business
// clock), and the earliest end of a live lease (real clock), the zero time for none.
func (q *Queries) NextCallWork(ctx context.Context, arg NextCallWorkParams) (NextCallWorkRow, error) {
	row := q.db.QueryRow(ctx, nextCallWork, arg.Now, arg.OrgID)
	var i NextCallWorkRow
	err := row.Scan(&i.FreeAt, &i.LeaseEnd)
	return i, err
}

const nextGatewayProbe = `-- name: NextGatewayProbe :one
SELECT coalesce(min(gateway_next_probe_at)
                    FILTER (WHERE gateway_probe_lease_until IS NULL OR gateway_probe_lease_until <= $1::timestamptz),
                '0001-01-01 00:00:00+00')::timestamptz AS free_at,
       coalesce(min(gateway_probe_lease_until) FILTER (WHERE gateway_probe_lease_until > $1::timestamptz),
                '0001-01-01 00:00:00+00')::timestamptz AS lease_end
FROM connections
WHERE org_id = $2 AND gateway_broken_since IS NOT NULL AND deleted_at IS NULL
`

type NextGatewayProbeParams struct {
	Now   time.Time
	OrgID int64
}

type NextGatewayProbeRow struct {
	FreeAt   time.Time
	LeaseEnd time.Time
}

// NextGatewayProbe is when the next probe of a Broken gateway that is not deleted is due (business clock), and the
// earliest end of a live lease of one (real clock), the zero time for none.
func (q *Queries) NextGatewayProbe(ctx context.Context, arg NextGatewayProbeParams) (NextGatewayProbeRow, error) {
	row := q.db.QueryRow(ctx, nextGatewayProbe, arg.Now, arg.OrgID)
	var i NextGatewayProbeRow
	err := row.Scan(&i.FreeAt, &i.LeaseEnd)
	return i, err
}

const notifyCalls = `-- name: NotifyCalls :exec
SELECT pg_notify($1::text, '')
`

// NotifyCalls wakes the gateway senders of every replica once the transaction commits.
func (q *Queries) NotifyCalls(ctx context.Context, channel string) error {
	_, err := q.db.Exec(ctx, notifyCalls, channel)
	return err
}

const previousCall = `-- name: PreviousCall :one
SELECT state, ended_at
FROM gateway_calls
WHERE org_id = $1 AND connection_id = $2 AND user_id = $3 AND first_attempt_at IS NOT NULL
ORDER BY id DESC
LIMIT 1
`

type PreviousCallParams struct {
	OrgID        int64
	ConnectionID int64
	UserID       int64
}

type PreviousCallRow struct {
	State   string
	EndedAt pgtype.Timestamptz
}

// PreviousCall reads the latest call of a User through a gateway that went — whose first attempt was made, or tried —
// with its state and its end, null while it is being sent.
func (q *Queries) PreviousCall(ctx context.Context, arg PreviousCallParams) (PreviousCallRow, error) {
	row := q.db.QueryRow(ctx, previousCall, arg.OrgID, arg.ConnectionID, arg.UserID)
	var i PreviousCallRow
	err := row.Scan(&i.State, &i.EndedAt)
	return i, err
}

const pruneCodes = `-- name: PruneCodes :execrows
WITH doomed AS MATERIALIZED (
    SELECT o.id FROM gateway_contact_codes o
    WHERE o.org_id = $1 AND o.expires_at < $2::timestamptz
    ORDER BY o.id
    LIMIT $3
    FOR UPDATE SKIP LOCKED
)
DELETE FROM gateway_contact_codes k
USING doomed d
WHERE k.org_id = $1 AND k.id = d.id
`

type PruneCodesParams struct {
	OrgID     int64
	Before    time.Time
	BatchSize int32
}

// PruneCodes deletes up to batch_size codes that expired before @before, used and void ones included. A code being
// checked is skipped and taken at the next run. The batch is chosen once, in a materialized CTE, as PruneLinkRequests
// does.
func (q *Queries) PruneCodes(ctx context.Context, arg PruneCodesParams) (int64, error) {
	result, err := q.db.Exec(ctx, pruneCodes, arg.OrgID, arg.Before, arg.BatchSize)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const pruneEndedCalls = `-- name: PruneEndedCalls :execrows
WITH doomed AS MATERIALIZED (
    SELECT c.id FROM gateway_calls c
    WHERE c.org_id = $1 AND c.state IN ('accepted', 'not_delivered', 'dropped')
      AND c.ended_at <= $2::timestamptz
      AND NOT EXISTS (SELECT 1 FROM gateway_call_items i WHERE i.org_id = c.org_id AND i.call_id = c.id)
    ORDER BY c.id
    LIMIT $3
    FOR UPDATE SKIP LOCKED
)
DELETE FROM gateway_calls g
USING doomed d
WHERE g.org_id = $1 AND g.id = d.id
`

type PruneEndedCallsParams struct {
	OrgID     int64
	Now       time.Time
	BatchSize int32
}

// PruneEndedCalls deletes up to batch_size calls that ended at or before @now and are about no Alert Group any more:
// the retention of Alert Groups deleted every one of theirs, and its cascade their items. The batch is chosen once, in
// a materialized CTE, as PruneCodes does; a call that another transaction holds is taken at the next run.
func (q *Queries) PruneEndedCalls(ctx context.Context, arg PruneEndedCallsParams) (int64, error) {
	result, err := q.db.Exec(ctx, pruneEndedCalls, arg.OrgID, arg.Now, arg.BatchSize)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const recordCallRetry = `-- name: RecordCallRetry :execrows
UPDATE gateway_calls
SET attempts = attempts + 1, first_failed_at = coalesce(first_failed_at, $1::timestamptz),
    next_attempt_at = $2::timestamptz, lease_owner = NULL, lease_until = NULL, last_error_class = $3::text,
    last_error = $4::text
WHERE org_id = $5 AND id = $6 AND state = 'sending' AND lease_owner = $7::text
`

type RecordCallRetryParams struct {
	Now        time.Time
	At         time.Time
	ErrorClass string
	Error      pgtype.Text
	OrgID      int64
	ID         int64
	Owner      string
}

// RecordCallRetry counts a failed attempt of the budget and makes the call due again at a later time.
func (q *Queries) RecordCallRetry(ctx context.Context, arg RecordCallRetryParams) (int64, error) {
	result, err := q.db.Exec(ctx, recordCallRetry,
		arg.Now,
		arg.At,
		arg.ErrorClass,
		arg.Error,
		arg.OrgID,
		arg.ID,
		arg.Owner,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const recordWrongCode = `-- name: RecordWrongCode :one
UPDATE gateway_contact_codes
SET attempts = attempts + 1,
    voided_at = CASE WHEN attempts + 1 >= $1::bigint THEN $2::timestamptz ELSE voided_at END
WHERE org_id = $3 AND id = $4
RETURNING attempts
`

type RecordWrongCodeParams struct {
	MaxAttempts int64
	Now         time.Time
	OrgID       int64
	ID          int64
}

// RecordWrongCode counts a wrong code; the attempt that reaches max_attempts voids the code.
func (q *Queries) RecordWrongCode(ctx context.Context, arg RecordWrongCodeParams) (int64, error) {
	row := q.db.QueryRow(ctx, recordWrongCode,
		arg.MaxAttempts,
		arg.Now,
		arg.OrgID,
		arg.ID,
	)
	var attempts int64
	err := row.Scan(&attempts)
	return attempts, err
}

