const rescheduleCall = `-- name: RescheduleCall :execrows
UPDATE gateway_calls
SET next_attempt_at = $1::timestamptz, lease_owner = NULL, lease_until = NULL,
    first_failed_at = coalesce(first_failed_at, $2::timestamptz),
    last_error_class = coalesce($3::text, last_error_class),
    last_error = coalesce($4::text, last_error)
WHERE org_id = $5 AND id = $6 AND state IN ('waiting', 'sending') AND lease_owner = $7::text
`

type RescheduleCallParams struct {
	At         time.Time
	FailedAt   pgtype.Timestamptz
	ErrorClass pgtype.Text
	Error      pgtype.Text
	OrgID      int64
	ID         int64
	Owner      string
}

// RescheduleCall makes a call due again at a later time without counting an attempt — no limiter token was free, or
// the gateway asked to wait — and frees its lease. A gateway's RetryAfter passes failed_at, which starts the time
// budget of delivery.transient_budget when no failure started it yet.
func (q *Queries) RescheduleCall(ctx context.Context, arg RescheduleCallParams) (int64, error) {
	result, err := q.db.Exec(ctx, rescheduleCall,
		arg.At,
		arg.FailedAt,
		arg.ErrorClass,
		arg.Error,
		arg.OrgID,
		arg.ID,
		arg.Owner,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const startCall = `-- name: StartCall :execrows
UPDATE gateway_calls
SET state = 'sending', contact_id = $1::bigint, language = $2::text, text = $3::text,
    action_data = $4::text, button_key_id = $5::text,
    first_attempt_at = $6::timestamptz, next_attempt_at = $6::timestamptz, not_before = coalesce(not_before, $6),
    lease_until = $7::timestamptz
WHERE org_id = $8 AND id = $9 AND state = 'waiting' AND lease_owner = $10::text
`

type StartCallParams struct {
	ContactID   pgtype.Int8
	Language    string
	Text        string
	ActionData  pgtype.Text
	ButtonKeyID pgtype.Text
	Now         time.Time
	LeaseUntil  time.Time
	OrgID       int64
	ID          int64
	Owner       string
}

// StartCall makes the first attempt of a waiting call: it keeps its contact, its text, its language and its action
// data, signed by the key button_key_id, from now on, takes no more Alert Groups and is due now, its lease renewed for
// the attempt.
func (q *Queries) StartCall(ctx context.Context, arg StartCallParams) (int64, error) {
	result, err := q.db.Exec(ctx, startCall,
		arg.ContactID,
		arg.Language,
		arg.Text,
		arg.ActionData,
		arg.ButtonKeyID,
		arg.Now,
		arg.LeaseUntil,
		arg.OrgID,
		arg.ID,
		arg.Owner,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

